(8608, 817, '_elementor_version', '4.1.3'),
(8609, 817, '_elementor_pro_version', '4.1.1'),
(8610, 817, '_elementor_migrations_state_d2a1', '4.1.4:4.1.2:595e50d38ae27a4ec16e0e0a9df00b29'),
