(8615, 817, '_elementor_page_assets', 'a:2:{s:6:\"styles\";a:2:{i:0;s:14:\"widget-heading\";i:1;s:12:\"widget-image\";}s:7:\"scripts\";a:1:{i:0;s:18:\"elementor-frontend\";}}'),
(8616, 817, '_elementor_element_cache', '{\"timeout\":1782810264,\"value\":{\"content\":\"<div class=\"elementor-element elementor-element-3b94d6d e-flex e-con-boxed e-con e-parent\" data-id=\"3b94d6d\" data-element_type=\"container\" data-e-type=\"container\">nttttt<div class=\"e-con-inner\">ntttt<div class=\"elementor-element elementor-element-5305667 elementor-widget elementor-widget-heading\" data-id=\"5305667\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"heading.default\">nttttt<h1 class=\"elementor-heading-title elementor-size-default\">Lu2019AILLEURS COMMENCE ICI!</h1>tttt</div>nttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-700846a e-flex e-con-boxed e-con e-parent\" data-id=\"700846a\" data-element_type=\"container\" data-e-type=\"container\">nttttt<div class=\"e-con-inner\">ntt[elementor-element k=\"6ac5a3189cc32396b48afe3146bbdb88\" data=\"\"]ttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-2d20aa6 e-flex e-con-boxed e-con e-parent\" data-id=\"2d20aa6\" data-element_type=\"container\" data-e-type=\"container\">nttttt<div class=\"e-con-inner\">ntt<div class=\"elementor-element elementor-element-8dfe67b e-con-full e-flex e-con e-child\" data-id=\"8dfe67b\" data-element_type=\"container\" data-e-type=\"container\">ntttt<div class=\"elementor-element elementor-element-6dc2c8f elementor-absolute elementor-widget elementor-widget-image\" data-id=\"6dc2c8f\" data-element_type=\"widget\" data-e-type=\"widget\" data-settings=\"{&quot;_position&quot;:&quot;absolute&quot;}\" data-widget_type=\"image.default\">nttttttttttttttt<img width=\"150\" height=\"150\" src=\"https://bgodbillot.alwaysdata.net/wp-content/uploads/2026/05/Groupe_2237-150x150.png\" class=\"attachment-thumbnail size-thumbnail wp-image-335\" alt=\"\" srcset=\"https://bgodbillot.alwaysdata.net/wp-content/uploads/2026/05/Groupe_2237-150x150.png 150w, https://bgodbillot.alwaysdata.net/wp-content/uploads/2026/05/Groupe_2237-100x100.png 100w\" sizes=\"(max-width: 150px) 100vw, 150px\" />ttttttttttttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-442417b e-con-full e-flex e-con e-child\" data-id=\"442417b\" data-element_type=\"container\" data-e-type=\"container\">ntttt<div class=\"elementor-element elementor-element-2d111a0 elementor-align-center elementor-widget elementor-widget-button\" data-id=\"2d111a0\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"button.default\">ntttttttttt<a class=\"elementor-button elementor-button-link elementor-size-sm\" href=\"#\">ntttttt<span class=\"elementor-button-content-wrapper\">nttttttttt<span class=\"elementor-button-text\">Du00c9COUVRIR LE DOMAINE</span>nttttt</span>nttttt</a>ntttttttt</div>ntttt</div>nttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-9ef7bdc e-con-full e-flex e-con e-parent\" data-id=\"9ef7bdc\" data-element_type=\"container\" data-e-type=\"container\">ntttt<div class=\"elementor-element elementor-element-1aa1f30 elementor-widget elementor-widget-html\" data-id=\"1aa1f30\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"html.default\">nttttt<style>rn/* Police d\'u00e9criture pour le bouton \"Du00c9COUVRIR LA CUVu00c9E\" */rn@font-face {rn  font-family: \'Fira Sans\';rn  src: url(\'../fonts/FiraSans-Regular.ttf\') format(\'truetype\');rn}rn/* Police d\'u00e9criture pour le titre et le sous titre */rn@font-face{rn  font-family: \'Courier Prime\';rn  src: url(\'../fonts/CourierPrime-Regular.ttf\') format(\'truetype\');rn}rn/* TITRE ET SOUS TITRE */rn.titre_slide{rn  display: flex;rn  flex-direction: column;rn  align-items: center;rn  letter-spacing: 0.05em;rn  line-height: 128px;rn}rnh2{rn  font-family: \'Courier Prime\', \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;rn  font-weight: bold;rn  font-size: 80px;rn}rnh3{rn  font-family: \'Fira Sans\', \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;rn  font-weight: lighter;rn  font-size: 60px;rn}rn/* SLIDE */rn* {rn  margin: 0;rn  padding: 0;rn  box-sizing: border-box;rn}rnbody {rn  background: transparent;rn  font-family: \'Georgia\', serif;rn  overflow-x: hidden;rn}rn/* Conteneur principal du slider */rn.slider_complet {rn  position: relative;rn  width: 100%;rn  overflow: hidden;rn  padding-bottom: 50px;rn}rn/* Piste des fonds : empilu00e9s, un seul visible u00e0 la fois */rn.fonds_piste {rn  position: relative;rn  width: 100%;rn}rn/* Tous les fonds sont cachu00e9s par du00e9faut */rn.fond {rn  display: none;rn  width: 100%;rn}rn/* Fond actif visible avec fadeIn */rn.fond.actif {rn  display: block;rn  animation: fadeIn 0.5s ease;rn}rn.fond img {rn  width: 100%;rn  height: auto;rn  display: block;rn}rn/* Piste des bouteilles : flex horizontal */rn.bouteilles_piste {rn  position: absolute;rn  top: 0;rn  left: 0;rn  width: 100%;rn  height: 100%;rn  display: flex;rn  align-items: center;rn  transition: transform 0.5s ease;rn  pointer-events: auto;rn}rn/* Chaque bouteille occupe 1/3 de la largeur */rn.bouteille {rn  display: block;rn  position: relative;rn  min-width: 33.33%;rn  height: 100%;rn  transition: transform 0.5s ease, opacity 0.5s ease;rn  opacity: 1;rn  transform: scale(0.8);rn}rn/* Bouteille mise en avant */rn.bouteille.actif {rn  opacity: 1;rn  transform: scale(1) translateX(8%);rn}rn.bouteille img {rn  width: auto;rn  height: 100%;rn  max-height: 800px;rn  display: block;rn  margin: 0 auto;rn}rn/* Bouteille pru00e9cu00e9dente : u00e0 moitiu00e9 sortie u00e0 gauche */rn.bouteille.precedent {rn  opacity: 1;rn  transform: scale(0.8) translateX(-60%);rn}rn/* Bouteille suivante : u00e0 moitiu00e9 sortie u00e0 droite */rn.bouteille.suivant {rn  opacity: 1;rn  transform: scale(0.8) translateX(70%);rn}rn/* Empu00eache la zone de su00e9lection des bouteilles */rn.bouteilles_piste,rn.bouteille,rn.bouteille img {rn  user-select: none;rn  -webkit-user-select: none;rn  -webkit-user-drag: none;rn}rn/* FLECHES ET BOUTON NAVIGATION */rn/* Barre de navigation */rn.slide_navigation {rn  position: absolute;rn  bottom: 0;rn  left: 50%;rn  transform: translateX(-50%);rn  display: flex;rn  align-items: stretch;rn  padding: 0;rn}rn/* Boutons flu00e8ches */rn.bouton_navigation {rn  background: #E8941A;rn  border: none;rn  width: 30px;rn  cursor: pointer;rn  display: flex;rn  align-items: center;rn  justify-content: center;rn  padding: 0 8px;rn}rn.bouton_navigation img {rn  width: 10px;rn  height: auto;rn  pointer-events: none;rn}rn/* Bouton Du00c9COUVRIR LA CUVu00c9E */rn.decouverte_cuvee {rn  font-size: 20px;rn  font-family: \'Fira Sans\', \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;rn  letter-spacing: 3px;rn  color: #FFFFFF;rn  text-transform: uppercase;rn  background: #E8941A;rn  border: none;rn  padding: 10px 24px;rn  cursor: pointer;rn}rn/* Animation de changement pour les fonds */rn@keyframes fadeIn {rn  from { opacity: 0; }rn  to   { opacity: 1; }rn}rn</style>rnrn<!-- Titre et Sous titre -->rn    <div class=\"titre_slide\">rn        <h2>LES u00c9LIXIRS DE CAMILLE</h2>rn        <h3>LES RATAFIAS IG</h3>rn    </div>rnrn    <!-- Conteneur principal du slider -->rn    <div class=\"slider_complet\">rnrn        <!-- Fonds : changement simple par fadeIn -->rn        <div class=\"fonds_piste\">rnrn            <!-- Fond 1 : affichu00e9 par du00e9faut -->rn            <div class=\"fond actif\">rn                <img src=\"/wp-content/uploads/2026/06/DECOR1-1-scaled.png\" alt=\"Fond du slide nu00b01\">rn            </div>rnrn            <!-- Fond 2 -->rn            <div class=\"fond\">rn                <img src=\"/wp-content/uploads/2026/06/DECOR2-scaled.png\" alt=\"Fond du slide nu00b02\">rn            </div>rnrn            <!-- Fond 3 -->rn            <div class=\"fond\">rn                <img src=\"/wp-content/uploads/2026/06/DECOR3-scaled.png\" alt=\"Fond du slide nu00b03\">rn            </div>rnrn            <!-- Fond 4 -->rn            <div class=\"fond\">rn                <img src=\"/wp-content/uploads/2026/06/DECOR4-scaled.png\" alt=\"Fond du slide nu00b04\">rn            </div>rnrn        </div>rnrn        <!-- Bouteilles : carrousel avec 3 visibles simultanu00e9ment -->rn        <div class=\"bouteilles_piste\">rnrn            <!-- Bouteille 1 : active par du00e9faut -->rn            <div class=\"bouteille actif\">rn                <img src=\"/wp-content/uploads/2026/06/bouteille1.png\" alt=\"Bouteille nu00b01\">rn            </div>rnrn            <!-- Bouteille 2 -->rn            <div class=\"bouteille suivant\">rn                <img src=\"/wp-content/uploads/2026/06/bouteille2.png\" alt=\"Bouteille nu00b02\">rn            </div>rnrn            <!-- Bouteille 3 -->rn            <div class=\"bouteille\">rn                <img src=\"/wp-content/uploads/2026/06/bouteille3.png\" alt=\"Bouteille nu00b03\">rn            </div>rnrn            <!-- Bouteille 4 -->rn            <div class=\"bouteille precedent\">rn                <img src=\"/wp-content/uploads/2026/06/bouteille4.png\" alt=\"Bouteille nu00b04\">rn            </div>rnrn        </div>rnrn        <!-- Navigation du slider -->rn        <div class=\"slide_navigation\">rnrn            <!-- Bouton slide pru00e9cu00e9dent -->rn            <button class=\"bouton_navigation\" id=\"bouton_precedent\">rn                <img src=\"/wp-content/uploads/2026/05/direction_gauche.png\" alt=\"Bouton pru00e9cu00e9dent\">rn            </button>rnrn            <!-- Bouton de validation pour voir la cuvu00e9e -->rn            <span class=\"decouverte_cuvee\">Du00c9COUVRIR LA CUVu00c9E</span>rnrn            <!-- Bouton slide suivant -->rn            <button class=\"bouton_navigation\" id=\"bouton_suivant\">rn                <img src=\"/wp-content/uploads/2026/05/direction_droite.png\" alt=\"Bouton suivant\">rn            </button>rnrn        </div>rnrn    </div>rn    rn    <script>// Su00e9lection des fonds et des bouteilles su00e9paru00e9mentrnconst fonds = document.querySelectorAll(\'.fond\');rnconst bouteilles = document.querySelectorAll(\'.bouteille\');rnlet current = 0;rnconst total = fonds.length;rnrn// Index pru00e9cu00e9dent avec bouclernfunction getPrev(index) {rn    return (index - 1 + total) % total;rn}rnrn// Index suivant avec bouclernfunction getNext(index) {rn    return (index + 1) % total;rn}rnrn// Mise u00e0 jour des fondsrnfunction updateFond() {rn    fonds.forEach(fond => fond.classList.remove(\'actif\'));rn    fonds[current].classList.add(\'actif\');rn}rnrn// Mise u00e0 jour des bouteilles : carrousel avec glissementrnfunction updateBouteilles() {rn    bouteilles.forEach((b, i) => {rn        b.classList.remove(\'actif\', \'precedent\', \'suivant\');rn        b.style.opacity = \'0\';rn        b.style.order = \'99\';rn    });rnrn    const prev = getPrev(current);rn    const next = getNext(current);rnrn    bouteilles[prev].classList.add(\'precedent\');rn    bouteilles[prev].style.order = \'1\';rn    bouteilles[prev].style.opacity = \'1\';rnrn    bouteilles[current].classList.add(\'actif\');rn    bouteilles[current].style.order = \'2\';rn    bouteilles[current].style.opacity = \'1\';rnrn    bouteilles[next].classList.add(\'suivant\');rn    bouteilles[next].style.order = \'3\';rn    bouteilles[next].style.opacity = \'1\';rnrn    const piste = document.querySelector(\'.bouteilles_piste\');rn    piste.style.transform = \'translateX(0%)\';rn}rnrn// Couleurs de navigation par slidernconst couleurs = [\'#161B4B\', \'#E8941A\', \'#107D81\', \'#E9453F\'];rnrn// Mise u00e0 jour de la couleur de navigationrnfunction updateNavigation() {rn    const boutons = document.querySelectorAll(\'.bouton_navigation\');rn    const label = document.querySelector(\'.decouverte_cuvee\');rn    const h2 = document.querySelector(\'.titre_slide h2\');rn    const h3 = document.querySelector(\'.titre_slide h3\');rn    const couleur = couleurs[current];rn   rn// Changer la couleur du boutons et des flu00e8chesrn    boutons.forEach(b => b.style.backgroundColor = couleur);rn    label.style.backgroundColor = couleur;rnrnrn// Changer la couleur des titres h2 et h3rn    h2.style.color = couleur;rn    h3.style.color = couleur;rnrn}rnrn// === Gestion du swipe u00e0 la souris sur les bouteilles ===rnconst piste = document.querySelector(\'.bouteilles_piste\');rnlet startX = 0;rnlet isDragging = false;rnconst seuilSwipe = 50; // distance minimale en pixels pour valider un swipernrn// Clic enfoncu00e9 : du00e9but du glissementrnpiste.addEventListener(\'mousedown\', (e) => {rn    startX = e.clientX;rn    isDragging = true;rn});rnrn// Relu00e2chement du clic : fin du glissementrnpiste.addEventListener(\'mouseup\', (e) => {rn    if (!isDragging) return;rn    isDragging = false;rnrn    const endX = e.clientX;rn    const distance = endX - startX;rnrn    if (distance > seuilSwipe) {rn        // Glissement vers la droite : bouteille pru00e9cu00e9dentern        current = getPrev(current);rn        updateSlider();rn    } else if (distance < -seuilSwipe) {rn        // Glissement vers la gauche : bouteille suivantern        current = getNext(current);rn        updateSlider();rn    }rn});rnrn// Si la souris sort de la zone pendant le clic, on annulernpiste.addEventListener(\'mouseleave\', () => {rn    isDragging = false;rn});rnrn// Fonction principalernfunction updateSlider() {rn    updateFond();rn    updateBouteilles();rn    updateNavigation();rn}rnrn// Bouton pru00e9cu00e9dentrndocument.getElementById(\'bouton_precedent\').addEventListener(\'click\', () => {rn    current = getPrev(current);rn    updateSlider();rn});rnrn// Bouton suivantrndocument.getElementById(\'bouton_suivant\').addEventListener(\'click\', () => {rn    current = getNext(current);rn    updateSlider();rn});rnrn// Initialisation au chargementrnupdateSlider();rnrnrn</script>tttt</div>ntttt</div>ntt\",\"scripts\":[],\"styles\":[]}}'),
